(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let manualOff=false;try{manualOff=localStorage.getItem('sahra-motion')==='off'}catch{}const off=()=>reduced.matches||manualOff;
 const nav=document.querySelector('#categories');const indicator=document.createElement('span');indicator.className='category-indicator';indicator.setAttribute('aria-hidden','true');nav.append(indicator);
 function positionIndicator(){const active=nav.querySelector('[aria-pressed="true"]');if(active){indicator.style.setProperty('--indicator-left',active.offsetLeft+'px');indicator.style.setProperty('--indicator-width',active.offsetWidth+'px')}}
 const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal-visible');observer.unobserve(entry.target)}}),{threshold:.05,rootMargin:'35px 0px'}):null;
 function refresh(){positionIndicator();if(!observer||off())return;observer.disconnect();document.querySelectorAll('.photo-card,.section-title,.section-description').forEach((element,index)=>{element.classList.add('reveal');element.style.setProperty('--reveal-delay',element.classList.contains('photo-card')?`${index%3*55}ms`:'0ms');observer.observe(element)});onScroll()}
 let pending=false;function onScroll(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;const max=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--page-progress',max>0?Math.min(1,scrollY/max):0);if(!off())document.documentElement.style.setProperty('--stamp-turn',`${scrollY*.018}deg`);document.querySelector('.filterbar')?.classList.toggle('is-stuck',document.querySelector('.filterbar').getBoundingClientRect().top<=0)})}
 document.addEventListener('pointermove',event=>{if(off()||!matchMedia('(hover:hover)').matches)return;const card=event.target.closest('.photo-card');if(!card)return;const rect=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${((event.clientX-rect.left)/rect.width-.5)*3}deg`);card.style.setProperty('--tilt-y',`${-((event.clientY-rect.top)/rect.height-.5)*3}deg`)});
 document.addEventListener('pointerout',event=>{const card=event.target.closest('.photo-card');if(card&&!card.contains(event.relatedTarget)){card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y')}});
 const dialog=document.querySelector('dialog');let closeTimer;
 function closeDialog(){if(!dialog.open)return true;if(off()){dialog.close();return true}if(closeTimer)return true;dialog.classList.remove('is-opening');dialog.classList.add('is-closing');closeTimer=setTimeout(()=>{dialog.close();dialog.classList.remove('is-closing');closeTimer=null},200);return true}
 dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog()});
 window.sahraMotion={refresh,closeDialog,openDialog(){clearTimeout(closeTimer);closeTimer=null;dialog.classList.remove('is-closing','is-opening');void dialog.offsetWidth;if(!off())dialog.classList.add('is-opening')},heart(id){if(off())return;document.querySelectorAll(`[data-save="${id}"]`).forEach(element=>element.animate([{transform:'scale(1)'},{transform:'scale(1.24) rotate(-8deg)',offset:.4},{transform:'scale(1)'}],{duration:380,easing:'cubic-bezier(.2,.8,.2,1)'}));document.querySelector('#saved-count').animate([{transform:'translateY(0)'},{transform:'translateY(-3px)'},{transform:'translateY(0)'}],{duration:300})}};
 function syncMotion(){document.body.classList.toggle('motion-ready',!off()&&!!observer);document.body.classList.toggle('motion-paused',off());const button=document.querySelector('#motion-toggle');button.setAttribute('aria-pressed',String(!off()));button.setAttribute('aria-label',off()?'Turn animations on':'Turn animations off');button.querySelector('.motion-label').textContent=off()?'Motion off':'Motion on';refresh()}
 document.querySelector('#motion-toggle').addEventListener('click',()=>{if(reduced.matches){announce('Your device is set to reduced motion.');return}manualOff=!manualOff;try{localStorage.setItem('sahra-motion',manualOff?'off':'on')}catch{}syncMotion()});reduced.addEventListener('change',syncMotion);syncMotion();addEventListener('scroll',onScroll,{passive:true});addEventListener('resize',()=>{positionIndicator();onScroll()});document.fonts.ready.then(positionIndicator);onScroll();
})();
